{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximize the number of complete products produced, minimize total production hours used, or something else?"
  ],
  "rationale": "The response asks a single clarification question about the objective of the production plan, with examples provided for context but not as separate questions."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a required demand or minimum number of complete products that must be met, or is the only goal to produce as many complete products as possible within the capacity limits?"
  ],
  "rationale": "The response asks a single clarification question regarding the objective function (meeting a specific demand vs. maximizing production), which constitutes one independent semantic query."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each complete product, is exactly one unit of each of the three components required, or are the component quantities per product different?"
  ],
  "rationale": "The response asks a single clarification question regarding the component-to-product ratio, presenting two mutually exclusive options for the same policy."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a workshop produce all three components, or is each workshop restricted to producing only certain components?"
  ],
  "rationale": "The response asks a single clarification question regarding workshop production capabilities, presented as a binary choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the production quantities of the components required to be whole numbers (integers), or can they be fractional?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific constraint on variable types (integer vs. fractional)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a workshop produces more units of a component than are needed for the complete products, is that excess simply discarded, or does it have any value or penalty?"
  ],
  "rationale": "The response contains a single clarification question asking for the policy or consequence regarding excess production, which constitutes one independent semantic request."
}

